// Purchase orders rules — golden values. The prototype's own orders (HLT_POS + genPOs per project, PARTS prices and
// statuses, ALL_BYID activities) go through the domain functions and are compared with the prototype's render values
// (src/features/orders/orders.golden.json, generated by scripts/proto-golden-orders.ts: logic 4306–4337 run in
// node:vm, EN): KPI figures, status counts, row texts and colours, row buttons, the drawer stepper (every status,
// cancelled included), the part-status warnings, and the workflow after the shortfall drafts (Send for approval,
// Approve & order, My approvals Reject). Deliberate deviations are asserted explicitly (activity start dates the
// prototype cut, "Needed from 14ug A").
import { describe, expect, it } from 'vitest';
import { money } from '@/lib/format';
import { fmtDOfIso, partStatus, poStatus, splitActual, type PoStatus } from '@/server/db/codes';
import { PROTO, PROTO_GEN } from '@/server/prototype';
import golden from '@/features/orders/orders.golden.json';
import {
  PO_FLOW, PO_LATE_TEXT, canApprovePo, canPushPoToX3, canSubmitPo, filterPos, hasPartStatusIssue, isLatePo, isPoStatus, lineSummary, mockX3OrderRef, needText, orderHref,
  partWarnings, poApprovalItems, poKpis, poRisk, poRiskText, poStatusCounts, poSteps, poUnits, poValueEur, poX3State, type PoInput,
} from './orders';

/* eslint-disable @typescript-eslint/no-explicit-any */
const G = golden as any;
const PARTS: Record<string, any> = Object.fromEntries((PROTO.PARTS as any[]).map((p) => [p.ref, p]));
const ACTS: Record<string, any> = PROTO.ALL_BYID;
const PROJECTS = ['HLT-026', 'NDC-031', 'RCF-019', 'ERP-202', 'WSA-044', 'MSR-012'];
const LO = 'var(--color-accent-300)';
const OK = 'var(--color-text)';
const f = (k: number) => money(k, 'en');
const n = (v: number) => v.toLocaleString('en-US');
/** The prototype stripped the actual-date marker with `.replace(' A', '')`, which cut "Aug" / "Apr" (fixed here). */
const ACTUAL_STRIP_FIX: Record<string, string> = { 'Needed from 14ug A': 'Needed from 14 Aug', 'Needed from 15pr ’27': 'Needed from 15 Apr ’27' };

/** A prototype order (`[ref, ordered, received]` lines, label status) as the rules read it. */
function input(o: any, status?: string): PoInput {
  const st = poStatus.code(status ?? o.status) as PoStatus;
  const a = o.act ? ACTS[o.act] : null;
  return {
    number: o.id, supplier: o.supplier, status: st, origin: o.id >= 'PO-1100' && o.id < 'PO-2000' ? 'shortfall' : 'x3', x3Ref: null,
    lines: o.lines.map(([ref, q, r]: [string, number, number]) => ({
      ref, name: PARTS[ref]?.name ?? ref, orderedQty: q, receivedQty: st === 'received' ? q : r, unitPriceEur: PARTS[ref]?.price ?? 0, partStatus: partStatus.code(PARTS[ref].status),
    })),
    neededFor: a ? { code: a.id, name: a.n, startText: splitActual(a.s).text, percentComplete: a.pc } : null,
  };
}

const posOf = (code: string): PoInput[] => ((PROTO_GEN.genPOs[code] ?? []) as any[]).map((o) => input(o));

/** The prototype's row strings rebuilt from the rules. */
function row(o: PoInput) {
  const risk = poRisk(o);
  const late = isLatePo(o);
  return {
    id: o.number, supplier: o.supplier, lineSummary: lineSummary(o.lines.map((l) => l.ref)),
    lineCount: `${o.lines.length}${o.lines.length === 1 ? ' line' : ' lines'} · ${n(poUnits(o))} units${hasPartStatusIssue(o) ? ' · part status issue' : ''}`,
    value: f(poValueEur(o) / 1000), status: poStatus.label(o.status), expColor: late ? LO : 'var(--color-neutral-300)', need: needText(o), risk: poRiskText(risk),
    riskColor: late ? LO : 'var(--color-neutral-400)', canSubmit: canSubmitPo(o.status), canApprove: canApprovePo(o.status),
  };
}
const gRow = (r: any) => ({
  id: r.id, supplier: r.supplier, lineSummary: r.lineSummary, lineCount: r.lineCount, value: r.value, status: r.status, expColor: r.expColor, need: r.need,
  risk: ACTUAL_STRIP_FIX[r.risk] ?? r.risk, riskColor: r.riskColor, canSubmit: r.canSubmit, canApprove: r.canApprove,
});
const steps = (status: PoStatus) =>
  poSteps(status).map((s) => ({
    label: s.label, line: s.label !== 'Ordered', dot: s.reached ? 'var(--color-accent)' : 'var(--color-neutral-700)',
    ring: s.current ? '0 0 8px color-mix(in srgb, var(--color-accent) 60%, transparent)' : 'none', color: s.reached ? OK : 'var(--color-neutral-500)',
  }));
const warn = (o: PoInput) => {
  const w = partWarnings(o);
  return w.length ? w.map((x) => `${x.ref} is ${partStatus.label(x.status).toLowerCase()}`).join(' · ') + ' — resolve in PLM before this order is released.' : '';
};

function expectScreen(orders: PoInput[], g: any) {
  const k = poKpis(orders);
  expect([[k.open, `${k.total} orders in total`], [f(k.committedEur / 1000), 'Ordered, not cancelled'], [k.late, 'See Deliveries for goods receipt'], [k.awaitingApproval, 'Blocks ordering']])
    .toEqual(g.kpis.map((x: any) => [x.value, x.sub]));
  expect([k.late ? LO : OK, k.awaitingApproval ? LO : OK]).toEqual([g.kpis[2].color, g.kpis[3].color]);
  const counts = poStatusCounts(orders);
  expect([['All', String(orders.length)], ...PO_FLOW.map((s) => [poStatus.label(s), String(counts[s])])]).toEqual(g.chips.map((c: any) => [c.label, c.count]));
  expect(orders.map(row)).toEqual(g.rows.map(gRow));
  // Drawers present in the snapshot (every order by default; the drafts / the order that changed in the workflow).
  for (const o of orders.filter((x) => g.drawers[x.number])) {
    const d = g.drawers[o.number];
    expect(steps(o.status)).toEqual(d.steps);
    expect(warn(o)).toBe(d.warn);
    expect(o.lines.map((l) => l.ref)).toEqual(d.lines.map((l: any) => l.ref));
    expect([f(poValueEur(o) / 1000), needText(o)]).toEqual([d.meta[0].v, d.meta[3].v]);
    expect(d.meta[2].color).toBe(isLatePo(o) ? LO : OK);
  }
}

describe('purchase orders — prototype golden values (08 §2)', () => {
  it('PO_FLOW, status codes and the row buttons', () => {
    expect(PO_FLOW.map((s) => poStatus.label(s))).toEqual(PROTO.PO_FLOW);
    expect(PO_FLOW.filter(canSubmitPo)).toEqual(['draft']);
    expect(PO_FLOW.filter(canApprovePo)).toEqual(['awaiting_approval']);
    expect([isPoStatus('ordered'), isPoStatus('Ordered'), isPoStatus(null), isPoStatus('nope')]).toEqual([true, false, false, false]);
  });

  it.each(PROJECTS)('%s: KPIs, chips, rows and drawers reproduce poKpis / poChips / poRows / poVals', (code) => {
    expectScreen(posOf(code), G.projects.en[code]);
  });

  it('Harbor Line figures (spec 08 §2.4 spot-check): 5 open, €6.09M committed, 1 late (PO-1063), 1 awaiting approval', () => {
    const pos = posOf('HLT-026');
    expect(poKpis(pos)).toEqual({ open: 5, total: 6, committedEur: 6085800, late: 1, awaitingApproval: 1 });
    expect(pos.filter(isLatePo).map((o) => o.number)).toEqual(['PO-1063']);
    expect(pos.map((o) => [o.number, poValueEur(o)])).toEqual([
      ['PO-1041', 432480], ['PO-1052', 4986400], ['PO-1063', 420800], ['PO-1071', 218400], ['PO-1078', 19080], ['PO-1082', 8640],
    ]);
  });

  it('status chips filter the list (poFilter)', () => {
    const pos = posOf('HLT-026');
    for (const s of PO_FLOW) expect(filterPos(pos, s).map((o) => o.number)).toEqual(G.filters.en[poStatus.label(s)].rows);
    expect(filterPos(pos, null)).toHaveLength(6);
  });

  it('stepper of every status: Draft reached unless cancelled, Approved + Ordered from Ordered on, glow while Ordered / Partially received', () => {
    expect(Object.fromEntries(PO_FLOW.map((s) => [s, poSteps(s).map((x) => `${x.reached ? 'on' : 'off'}${x.current ? '*' : ''}`).join(' ')]))).toEqual({
      draft: 'on off off', awaiting_approval: 'on off off', ordered: 'on on on*', partially_received: 'on on on*', received: 'on on on', cancelled: 'off off off',
    });
  });

  it('the shortfall drafts, then Send for approval, Approve & order, and a My approvals rejection (createDrafts, setPO)', () => {
    const d = G.drafts.en['HLT-026'];
    const drafts = (d.draftPOs as any[]).map((o) => input(o));
    expect(d.poFilter).toBeNull();
    expectScreen([...posOf('HLT-026'), ...drafts], d);
    expect(drafts.every((o) => o.status === 'draft' && !o.neededFor && poRiskText(poRisk(o)) === '')).toBe(true);

    const flow = G.flow.en;
    const first = flow.first as string;
    const withStatus = (s: string) => [...posOf('HLT-026'), ...drafts.map((o) => (o.number === first ? { ...o, status: poStatus.code(s) as PoStatus } : o))];
    expectScreen(withStatus('Awaiting approval'), flow.submitted);
    expectScreen(withStatus('Ordered'), flow.approved);
    expect(flow.cancelledOverrides).toEqual({ 'PO-1082': 'Cancelled' });
    const cancelled = posOf('HLT-026').map((o) => (o.number === 'PO-1082' ? { ...o, status: 'cancelled' as PoStatus } : o));
    expectScreen(cancelled, flow.cancelled);
  });

  it('late-delivery risk: open orders whose activity started; the drawer no longer flags a cancelled order', () => {
    const late = posOf('HLT-026').find((o) => o.number === 'PO-1063')!;
    expect([isLatePo(late), poRiskText(poRisk(late))]).toEqual([true, PO_LATE_TEXT]);
    expect(isLatePo({ ...late, status: 'received' })).toBe(false);
    expect(isLatePo({ ...late, status: 'cancelled' })).toBe(false);
    expect(poRiskText(poRisk({ ...late, status: 'received' }))).toBe('Needed from 17 Aug');
    expect(poRisk({ status: 'draft', neededFor: null })).toBeNull();
  });

  it('Sage X3 flag: imported orders are X3, Keystone drafts are local until pushed once approved', () => {
    const base = { origin: 'shortfall' as const, x3Ref: null };
    expect(poX3State({ origin: 'x3', x3Ref: null })).toBe('x3');
    expect(poX3State(base)).toBe('local');
    expect(poX3State({ origin: 'rfq', x3Ref: 'X3-PO-1100' })).toBe('pushed');
    expect(PO_FLOW.filter((status) => canPushPoToX3({ ...base, status }))).toEqual(['ordered', 'partially_received', 'received']);
    expect(canPushPoToX3({ origin: 'x3', x3Ref: null, status: 'ordered' })).toBe(false);
    expect(canPushPoToX3({ origin: 'shortfall', x3Ref: 'X3-PO-1100', status: 'ordered' })).toBe(false);
    expect(mockX3OrderRef('PO-1100')).toBe('X3-PO-1100');
  });

  it('My approvals items reproduce apprItems (PO-1082 for the director and the PM), decided inline', () => {
    const o = posOf('HLT-026').find((x) => x.number === 'PO-1082')!;
    const items = poApprovalItems([{ number: o.number, supplier: o.supplier, valueEur: poValueEur(o), refs: o.lines.map((l) => l.ref), orderedOn: '2026-09-24', submittedBy: 'Fabien Bertrand' }], 'HLT-026', 'en', (iso) => fmtDOfIso(iso, 2026));
    expect(items).toEqual([
      {
        kind: 'po', id: 'PO-1082', title: 'Cotswold Fire Systems · €9k', sub: 'FD-DET-OPT', who: 'Fabien Bertrand', when: '24 Sep', whenIso: '2026-09-24',
        href: '/projects/HLT-026/orders?po=PO-1082', decision: { mode: 'purchase-order', projectCode: 'HLT-026', number: 'PO-1082' },
      },
    ]);
    expect(poApprovalItems([{ number: 'PO-1100', supplier: 'ArcelorMittal', valueEur: 238080, refs: ['KS-PLT-S355'], orderedOn: null, submittedBy: null }], 'HLT-026', 'fr', (iso) => fmtDOfIso(iso, 2026))[0])
      .toMatchObject({ title: 'ArcelorMittal · 238 k€', when: '', whenIso: null, who: '' });
    expect(orderHref('NDC-031', 'PO-3120')).toBe('/projects/NDC-031/orders?po=PO-3120');
  });
});
